def score(program: str) -> float:
    try:
        s = str(program)
        n = len(s) or 1
        a = sum(c.isalpha() for c in s) / n
        b = s.count(" ") / n
        v = a + b + s.count("\n") / n
        return min(1.0, max(0.0, v))
    except Exception:
        return 0.0

def score(program: str) -> float:
