    n = len(program)
    return min(1.0, n / 800.0)

import ast

def score(program: str) -> float:
    try:
        t = ast.parse(program)
    except Exception:
        return 0.0
    s = [(t, 0)]
    d = 0
    n = 0
    while s:
        x, k = s.pop()
        d += k
        n += 1
        for c in ast.iter_child_nodes(x):
            s.append((c, k + 1))
    return min(1.0, d / n / 12)

